  var first = true;
  await SessionLineScanner(fs: fs, path: path).scan((line) async {
    if (first) {
      first = false;
      headerSpan.add((line.start, line.end));
      return;
    }
    if (line.text.trim().isEmpty) return;
    recordsRead++;
    final customType = _sniffCustomType(line.text);
    final span = (line.start, line.end);
